# Fix: CONNECTOR_TIMEOUT via switch_replica on inventory_sync (snowflake)
# Generated by OrchestrAI Healing Agent
import json
import os, psycopg2
def fix_connector_switch_replica(pipeline_name: str, config: dict) -> dict:
    """Failover to read replica when primary times out."""
    replicas = config.get("replicas", [
        os.getenv("REPLICA_1_URL"), os.getenv("REPLICA_2_URL")
    ])
    for replica in filter(None, replicas):
        try:
            conn = psycopg2.connect(replica, connect_timeout=5)
            conn.close()
            # Persist the working replica
            os.environ["ACTIVE_DB_URL"] = replica
            return {"status": "switched", "replica": replica, "pipeline": pipeline_name}
        except Exception:
            continue
    return {"status": "all_replicas_failed", "tried": len(replicas)}

# Execute
if __name__ == "__main__":
    result = fix_switch_replica("inventory_sync", {"platform": "snowflake"})
    print(json.dumps(result, indent=2))
